    def reformat(self, s: str) -> str:
        chars = []
        nums = []
        for i in s:
            try:
                nums.append(int(i))
            except ValueError:
                chars.append(i)
        if abs(len(nums)-len(chars)) > 1:
            return ''

        out = [0]*len(s)
